const _geometry = TruckGeometry(size: Size(270, 152), wheelR: 18, floor: 98, bedCx: 82);

void main() {
  test('A03.frame 的每個東西都跟設計稿一樣（18 個時間點）', () {
    for (final r in (jsonDecode(_ref) as List).cast<Map<String, dynamic>>()) {
      final t = (r['t'] as num).toDouble();
      final f = truckFrame(t, const Size(390, 844), _geometry);
      final why = 't=$t';
      List<double> l(Object? v) => [for (final x in v as List) (x as num).toDouble()];
      void near(double a, double b, String what) => expect(a, closeTo(b, 1e-6), reason: '$why $what');
      final truck = l(r['truck']);
      near(f.truck.dx, truck[0], '卡車 x');
      near(f.truck.dy, truck[1], '卡車 y');
      near(f.wheelDeg, (r['wheel'] as num).toDouble(), '輪子');
      expect(f.lightOn, r['light'] == '#FFE27A', reason: '$why 倒車燈');
      near(-145 * f.gateOpen, (r['gate'] as num).toDouble(), '擋板');
      for (var i = 0; i < 2; i++) {
        final b = l((r['beep'] as List)[i]);
        near(f.beeps[i].opacity, b[0], '嗶$i 透明度');
        near(f.beeps[i].at.dx, b[1], '嗶$i x');
        near(f.beeps[i].at.dy, b[2], '嗶$i y');
        near(f.beeps[i].deg, b[3], '嗶$i 角度');
      }
      final side = l(r['side']), front = l(r['front']);
      expect(f.showFront, front[0] == 1, reason: '$why 正面');
      expect(!f.showFront, side[0] == 1, reason: '$why 側面');
      near(f.sideFoot.dx, side[1] + 54, '側面腳底 x');
      near(f.sideFoot.dy, side[2] + 93, '側面腳底 y');
      near(f.frontBase.dx, front[1] + 50, '正面 x');
      near(f.frontBase.dy, front[2] + 100, '正面 y');
      near(f.wave, front[3], '揮手');
      near(2 - f.squash, front[4], '擠（寬）');
      near(f.squash, front[5], '擠（高）');
      final say = l(r['say']);
      near(f.sayOpacity, say[0], '泡泡透明度');
      near(f.sayAt.dx, say[1], '泡泡 x');
      near(f.sayAt.dy, say[2], '泡泡 y');
      near(f.sayScale, say[3], '泡泡縮放');
      for (var i = 0; i < 3; i++) {
        final h = l((r['hearts'] as List)[i]);
        near(f.hearts[i].opacity, h[0], '愛心$i 透明度');
        near(f.hearts[i].at.dx, h[1], '愛心$i x');
        near(f.hearts[i].at.dy, h[2], '愛心$i y');
        near(f.hearts[i].scale, h[3], '愛心$i 縮放');
      }
      for (var i = 0; i < 4; i++) {
        final p = l((r['puffs'] as List)[i]);
        near(f.puffs[i].opacity, p[0], '煙$i 透明度');
        near(f.puffs[i].at.dx, p[1], '煙$i x');
        near(f.puffs[i].at.dy, p[2], '煙$i y');
        near(f.puffs[i].scale, p[3], '煙$i 縮放');
      }
      near(f.flash, (r['flash'] as num).toDouble(), '白光');
    }
  });
}
